        write_ready_oA = 1'b0;
      end
    else
      if (data_fault_validA)
        begin
          tag_addrA = data_parity_inv_qA.addr[CFG.LINE_ALIGN+:CFG.COUNT_ALIGN];
          tag_enableA = $unsigned(1<<data_parity_inv_qA.cset);
          tag_wdataA[CFG.TAG_WIDTH + 1:0] = '0;
          tag_wdataA[CFG.TAG_WIDTH + 2 + TagParity+:TagMetaTmrWidth] = '0;
          tag_writeA = 1'b1;
          data_fault_readyA = 1'b1;
          write_ready_oA = 1'b0;
        end
      else
        if (write_valid_iA)
          begin
            tag_addrA = write_addr_iA;
            tag_enableA = $unsigned(1<<write_set_iA);
            tag_writeA = 1'b1;
          end
        else
          if (faulty_hit_validA)
            begin
              tag_addrA = tag_req_qA>>CFG.LINE_ALIGN;
