logic [CFG.SET_COUNT * TagEntryWidth - 1:0] tag_sram_wdataB;
logic [CFG.SET_COUNT * TagEntryWidth - 1:0] tag_sram_wdataC;
logic [CFG.SET_COUNT * TagEntryWidth - 1:0] tag_rdata_flatA;
logic [CFG.SET_COUNT * TagEntryWidth - 1:0] tag_rdata_flatB;
logic [CFG.SET_COUNT * TagEntryWidth - 1:0] tag_rdata_flatC;
assign tag_sram_reqA = |tag_enableA;
assign tag_sram_reqB = |tag_enableB;
assign tag_sram_reqC = |tag_enableC;
assign tag_sram_wdataA = {CFG.SET_COUNT{tag_wdataA}};
assign tag_sram_wdataB = {CFG.SET_COUNT{tag_wdataB}};
