        register_file_1r_1w #(.ADDR_WIDTH($clog2(CFG.LINE_COUNT)), .DATA_WIDTH(TagEntryWidth)) i_tag_scmA (
            .clk(clk_iA),
            .ReadEnable(tag_enableA[i]&&!tag_writeA),
            .ReadAddr(tag_addrA),
            .ReadData(tag_rdataA[i]),
            .WriteEnable(tag_enableA[i]&&tag_writeA),
            .WriteAddr(tag_addrA),
            .WriteData(tag_wdataA)
          );

        register_file_1r_1w #(.ADDR_WIDTH($clog2(CFG.LINE_COUNT)), .DATA_WIDTH(TagEntryWidth)) i_tag_scmB (
            .clk(clk_iB),
