            .ReadData(tag_rdataB[i]),
            .WriteEnable(tag_enableB[i]&&tag_writeB),
            .WriteAddr(tag_addrB),
            .WriteData(tag_wdataB)
          );

        register_file_1r_1w #(.ADDR_WIDTH($clog2(CFG.LINE_COUNT)), .DATA_WIDTH(TagEntryWidth)) i_tag_scmC (
            .clk(clk_iC),
