        assign tag_rdataB[i] = tag_rdata_flatB[i * TagEntryWidth+:TagEntryWidth];
        assign tag_rdataC[i] = tag_rdata_flatC[i * TagEntryWidth+:TagEntryWidth];
      end

    tc_sram_impl #(.DataWidth(TagEntryWidth * CFG.SET_COUNT), .ByteWidth(TagEntryWidth), .NumWords(CFG.LINE_COUNT), .NumPorts(1), .SimInit("zeros"), .impl_in_t(sram_cfg_tag_t)) i_tag (
        .clk_i(clk_i),
        .rst_ni(rst_ni),
        .impl_i(sram_cfg_tag_i),
        .impl_o(),
        .req_i(tag_sram_req),
        .we_i(tag_write),
        .addr_i(tag_addr),
        .wdata_i(tag_sram_wdata),
        .be_i(tag_enable),
        .rdata_o(tag_rdata_flat)
      );
  end
