logic [CFG.SET_COUNT - 1:0] tag_meta_tmr_mismatchB;
logic [CFG.SET_COUNT - 1:0] tag_meta_tmr_mismatchC;
for(genvar i = 0; i<CFG.SET_COUNT; i++)
  begin : gen_tag_meta_tmr
    logic valid_faultA;
    logic valid_faultB;
    logic valid_faultC;
    logic error_faultA;
    logic error_faultB;
    logic error_faultC;

    TMR_voter_fail #(.VoterType(1)) i_valid_voterA (
        .a_i(tag_rdataA[i][CFG.TAG_WIDTH+1]),
        .b_i(tag_rdataA[i][CFG.TAG_WIDTH+2+TagParity]),
        .c_i(tag_rdataA[i][CFG.TAG_WIDTH+3+TagParity]),
        .majority_o(valid_votedA[i]),
        .fault_detected_o(valid_faultA)
      );

    TMR_voter_fail #(.VoterType(1)) i_valid_voterB (
        .a_i(tag_rdataB[i][CFG.TAG_WIDTH+1]),
        .b_i(tag_rdataB[i][CFG.TAG_WIDTH+2+TagParity]),
        .c_i(tag_rdataB[i][CFG.TAG_WIDTH+3+TagParity]),
        .majority_o(valid_votedB[i]),
        .fault_detected_o(valid_faultB)
      );

    TMR_voter_fail #(.VoterType(1)) i_valid_voterC (
        .a_i(tag_rdataC[i][CFG.TAG_WIDTH+1]),
        .b_i(tag_rdataC[i][CFG.TAG_WIDTH+2+TagParity]),
        .c_i(tag_rdataC[i][CFG.TAG_WIDTH+3+TagParity]),
        .majority_o(valid_votedC[i]),
        .fault_detected_o(valid_faultC)
      );

    TMR_voter_fail #(.VoterType(1)) i_error_voterA (
        .a_i(tag_rdataA[i][CFG.TAG_WIDTH]),
        .b_i(tag_rdataA[i][CFG.TAG_WIDTH+4+TagParity]),
        .c_i(tag_rdataA[i][CFG.TAG_WIDTH+5+TagParity]),
        .majority_o(error_votedA[i]),
        .fault_detected_o(error_faultA)
      );

    TMR_voter_fail #(.VoterType(1)) i_error_voterB (
        .a_i(tag_rdataB[i][CFG.TAG_WIDTH]),
        .b_i(tag_rdataB[i][CFG.TAG_WIDTH+4+TagParity]),
        .c_i(tag_rdataB[i][CFG.TAG_WIDTH+5+TagParity]),
        .majority_o(error_votedB[i]),
        .fault_detected_o(error_faultB)
      );

    TMR_voter_fail #(.VoterType(1)) i_error_voterC (
        .a_i(tag_rdataC[i][CFG.TAG_WIDTH]),
        .b_i(tag_rdataC[i][CFG.TAG_WIDTH+4+TagParity]),
        .c_i(tag_rdataC[i][CFG.TAG_WIDTH+5+TagParity]),
        .majority_o(error_votedC[i]),
        .fault_detected_o(error_faultC)
      );
    assign tag_meta_tmr_mismatchA[i] = valid_faultA|error_faultA;
    assign tag_meta_tmr_mismatchB[i] = valid_faultB|error_faultB;
    assign tag_meta_tmr_mismatchC[i] = valid_faultC|error_faultC;
  end
logic [CFG.SET_COUNT - 1:0] errorsA;
logic [CFG.SET_COUNT - 1:0] errorsB;
logic [CFG.SET_COUNT - 1:0] errorsC;
assign required_tagA = tag_req_qA.addr[CFG.FETCH_AW - 1:CFG.LINE_ALIGN + CFG.COUNT_ALIGN];
assign required_tagB = tag_req_qB.addr[CFG.FETCH_AW - 1:CFG.LINE_ALIGN + CFG.COUNT_ALIGN];
assign required_tagC = tag_req_qC.addr[CFG.FETCH_AW - 1:CFG.LINE_ALIGN + CFG.COUNT_ALIGN];
for(genvar i = 0; i<CFG.SET_COUNT; i++)
  begin : gen_line_hit
    assign line_hitA[i] = valid_votedA[i]&&tag_rdataA[i][CFG.TAG_WIDTH - 1:0]==required_tagA;
    assign line_hitB[i] = valid_votedB[i]&&tag_rdataB[i][CFG.TAG_WIDTH - 1:0]==required_tagB;
    assign line_hitC[i] = valid_votedC[i]&&tag_rdataC[i][CFG.TAG_WIDTH - 1:0]==required_tagC;
    assign errorsA[i] = error_votedA[i]&&line_hitA[i];
    assign errorsB[i] = error_votedB[i]&&line_hitB[i];
    assign errorsC[i] = error_votedC[i]&&line_hitC[i];
  end
assign tag_rsp_sA.error = |errorsA;
assign tag_rsp_sB.error = |errorsB;
assign tag_rsp_sC.error = |errorsC;
if (TagParity>0)
  begin : gen_tag_parity_error
    for(genvar i = 0; i<CFG.SET_COUNT; i++)
          begin : gen_tag_parity_error_individual
        assign tag_parity_error_dA[i] = tag_rdataA[i][CFG.TAG_WIDTH+1]&& (tag_rdataA[i][CFG.TAG_WIDTH+2]!=^tag_rdataA[i][CFG.TAG_WIDTH - 1:0]) ;
        assign tag_parity_error_dB[i] = tag_rdataB[i][CFG.TAG_WIDTH+1]&& (tag_rdataB[i][CFG.TAG_WIDTH+2]!=^tag_rdataB[i][CFG.TAG_WIDTH - 1:0]) ;
        assign tag_parity_error_dC[i] = tag_rdataC[i][CFG.TAG_WIDTH+1]&& (tag_rdataC[i][CFG.TAG_WIDTH+2]!=^tag_rdataC[i][CFG.TAG_WIDTH - 1:0]) ;
      end
    assign tag_rsp_sA.hit = | (line_hitA&~tag_parity_error_dA) ;
    assign tag_rsp_sB.hit = | (line_hitB&~tag_parity_error_dB) ;
    assign tag_rsp_sC.hit = | (line_hitC&~tag_parity_error_dC) ;
    assign faulty_hit_dA = |tag_parity_error_dA;
    assign faulty_hit_dB = |tag_parity_error_dB;
    assign faulty_hit_dC = |tag_parity_error_dC;
  end

else
  begin : gen_no_tag_parity_error
    assign tag_rsp_sA.hit = |line_hitA;
    assign tag_rsp_sB.hit = |line_hitB;
    assign tag_rsp_sC.hit = |line_hitC;
    assign tag_parity_error_dA = '0;
    assign tag_parity_error_dB = '0;
    assign tag_parity_error_dC = '0;
    assign faulty_hit_dA = '0;
    assign faulty_hit_dB = '0;
    assign faulty_hit_dC = '0;
  end

lzc #(.WIDTH(CFG.SET_COUNT)) i_lzcA (
    .in_i(line_hitA&~tag_parity_error_dA),
    .cnt_o(tag_rsp_sA.cset),
    .empty_o()
  );

lzc #(.WIDTH(CFG.SET_COUNT)) i_lzcB (
    .in_i(line_hitB&~tag_parity_error_dB),
    .cnt_o(tag_rsp_sB.cset),
    .empty_o()
  );

lzc #(.WIDTH(CFG.SET_COUNT)) i_lzcC (
    .in_i(line_hitC&~tag_parity_error_dC),
    .cnt_o(tag_rsp_sC.cset),
    .empty_o()
  );
tag_req_t tag_req_nextA;
tag_req_t tag_req_nextB;
tag_req_t tag_req_nextC;
