logic [CFG.SET_COUNT - 1:0] tag_parity_error_nextA;
logic [CFG.SET_COUNT - 1:0] tag_parity_error_nextB;
logic [CFG.SET_COUNT - 1:0] tag_parity_error_nextC;
logic faulty_hit_nextA;
logic faulty_hit_nextB;
logic faulty_hit_nextC;
assign tag_req_nextA = (req_validA&&req_readyA) ? tag_req_dA : tag_req_qA;
assign tag_req_nextB = (req_validB&&req_readyB) ? tag_req_dB : tag_req_qB;
assign tag_req_nextC = (req_validC&&req_readyC) ? tag_req_dC : tag_req_qC;
assign tag_valid_nextA = req_validA ? 1'b1 : tag_readyA ? 1'b0 : tag_validA;
assign tag_valid_nextB = req_validB ? 1'b1 : tag_readyB ? 1'b0 : tag_validB;
assign tag_valid_nextC = req_validC ? 1'b1 : tag_readyC ? 1'b0 : tag_validC;

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        tag_req_qA <= '0;
      end
    else
      begin
        tag_req_qA <= tag_req_nextVotedA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
    if (!rst_niB)
      begin
        tag_req_qB <= '0;
      end
    else
      begin
        tag_req_qB <= tag_req_nextVotedB;
      end
