  begin
    if (!rst_niC)
      begin
        tag_req_qC <= '0;
      end
    else
      begin
        tag_req_qC <= tag_req_nextVotedC;
      end
  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        tag_validA <= '0;
      end
    else
      begin
        tag_validA <= tag_valid_nextVotedA;
      end
  end

always_ff @( posedge clk_iB or negedge rst_niB )
  begin
    if (!rst_niB)
      begin
        tag_validB <= '0;
      end
    else
      begin
        tag_validB <= tag_valid_nextVotedB;
      end
  end

always_ff @( posedge clk_iC or negedge rst_niC )
  begin
    if (!rst_niC)
      begin
        tag_validC <= '0;
      end
    else
      begin
        tag_validC <= tag_valid_nextVotedC;
      end
  end
if (TagParity>0)
  begin : gen_tag_parity_error_ff
    assign tag_parity_error_nextA = (req_validA&&req_readyA) ? tag_parity_error_dA : tag_parity_error_qA;
    assign tag_parity_error_nextB = (req_validB&&req_readyB) ? tag_parity_error_dB : tag_parity_error_qB;
    assign tag_parity_error_nextC = (req_validC&&req_readyC) ? tag_parity_error_dC : tag_parity_error_qC;
    assign faulty_hit_nextA = (req_validA&&req_readyA||faulty_hit_readyA) ? ((faulty_hit_readyA&&!(req_validA&&req_readyA)) ? 1'b0 : faulty_hit_dA) : faulty_hit_qA;
    assign faulty_hit_nextB = (req_validB&&req_readyB||faulty_hit_readyB) ? ((faulty_hit_readyB&&!(req_validB&&req_readyB)) ? 1'b0 : faulty_hit_dB) : faulty_hit_qB;
    assign faulty_hit_nextC = (req_validC&&req_readyC||faulty_hit_readyC) ? ((faulty_hit_readyC&&!(req_validC&&req_readyC)) ? 1'b0 : faulty_hit_dC) : faulty_hit_qC;

    always_ff @( posedge clk_iA or negedge rst_niA )
      begin
        if (!rst_niA)
          begin
            tag_parity_error_qA <= '0;
          end
        else
          begin
            tag_parity_error_qA <= tag_parity_error_nextVotedA;
          end
      end

    always_ff @( posedge clk_iB or negedge rst_niB )
      begin
        if (!rst_niB)
          begin
            tag_parity_error_qB <= '0;
          end
        else
          begin
            tag_parity_error_qB <= tag_parity_error_nextVotedB;
          end
