    always_ff @( posedge clk_iC or negedge rst_niC )
      begin
        if (!rst_niC)
          begin
            tag_parity_error_qC <= '0;
          end
        else
          begin
            tag_parity_error_qC <= tag_parity_error_nextVotedC;
          end
      end

    always_ff @( posedge clk_iA or negedge rst_niA )
      begin
        if (!rst_niA)
          begin
            faulty_hit_qA <= '0;
          end
        else
          begin
            faulty_hit_qA <= faulty_hit_nextVotedA;
          end
      end

    always_ff @( posedge clk_iB or negedge rst_niB )
      begin
        if (!rst_niB)
          begin
            faulty_hit_qB <= '0;
          end
        else
          begin
            faulty_hit_qB <= faulty_hit_nextVotedB;
          end
      end

    always_ff @( posedge clk_iC or negedge rst_niC )
      begin
        if (!rst_niC)
          begin
            faulty_hit_qC <= '0;
          end
        else
          begin
            faulty_hit_qC <= faulty_hit_nextVotedC;
