else
  begin : gen_no_tag_parity_error_ff
    assign tag_parity_error_nextA = '0;
    assign tag_parity_error_nextB = '0;
    assign tag_parity_error_nextC = '0;
    assign faulty_hit_nextA = '0;
    assign faulty_hit_nextB = '0;
    assign faulty_hit_nextC = '0;
    assign tag_parity_error_qA = '0;
    assign tag_parity_error_qB = '0;
    assign tag_parity_error_qC = '0;
    assign faulty_hit_qA = '0;
    assign faulty_hit_qB = '0;
    assign faulty_hit_qC = '0;
  end
assign faulty_hit_validA = faulty_hit_qA;
assign faulty_hit_validB = faulty_hit_qB;
assign faulty_hit_validC = faulty_hit_qC;
